DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.save_activity_plan(uuid,date,jsonb,uuid,boolean)'::regprocedure) INTO f; f:=replace(f,'IF _plan IS NOT NULL THEN SELECT','IF _plan IS NULL AND EXISTS(SELECT 1 FROM activity_plans WHERE client_pipeline_id=_cp AND month=date_trunc(''month'',_month)::date) THEN RAISE EXCEPTION ''Edit the existing plan or create a revision from its approved version''; END IF; IF _plan IS NOT NULL THEN SELECT'); f:=replace(f,'IF p.id IS NULL OR p.status=''approved'' THEN','IF p.status=''approved'' AND EXISTS(SELECT 1 FROM activity_plans ap WHERE ap.client_pipeline_id=_cp AND ap.month=p.month AND ap.version>p.version) THEN RAISE EXCEPTION ''Edit the latest version instead''; END IF; IF p.id IS NULL OR p.status=''approved'' THEN'); EXECUTE f; SELECT pg_get_functiondef('public.activity_workspace(date,uuid,text,boolean)'::regprocedure) INTO f; f:=replace(f,'AND t.status<>''superseded'')))','AND t.stage=''publish'' AND t.status<>''superseded'')))'); EXECUTE f; END $$;
ALTER POLICY items_read ON public.activity_items USING(EXISTS(SELECT 1 FROM activity_plans p WHERE p.id=activity_items.plan_id AND activity_can_read(p.client_pipeline_id) AND (NOT has_role(auth.uid(),'client') OR p.status<>'draft')));
ALTER POLICY recurring_read ON public.recurring_tasks USING(EXISTS(SELECT 1 FROM activity_plans p WHERE p.id=recurring_tasks.plan_id AND activity_can_read(p.client_pipeline_id)) AND NOT has_role(auth.uid(),'client'));
ALTER POLICY history_read ON public.activity_task_history USING(EXISTS(SELECT 1 FROM recurring_tasks t JOIN activity_plans p ON p.id=t.plan_id WHERE t.id=activity_task_history.task_id AND activity_can_read(p.client_pipeline_id)) AND NOT has_role(auth.uid(),'client'));
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.activity_settings(text,text,text,uuid,boolean)'::regprocedure) INTO f; f:=replace(f,'IF _kind=''holiday'' THEN','IF coalesce(btrim(_name),'''')='''' THEN RAISE EXCEPTION ''Enter a name''; END IF; IF _kind=''holiday'' THEN'); f:=replace(f,'IF _id IS NULL THEN INSERT INTO activity_types','IF _id IS NULL AND NOT EXISTS(SELECT 1 FROM pipelines WHERE id=_pipeline AND code<>''business_development'') THEN RAISE EXCEPTION ''Choose a client-facing pipeline''; END IF; IF _id IS NULL THEN INSERT INTO activity_types'); EXECUTE f; END $$;